"""Render backtest results to results.md + results.png (regenerated by `flexcast backtest`)."""

import io

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import pandas as pd  # noqa: E402

from flexcast.backtest import PERFECT, BacktestConfig, BacktestResult, summarise, worst_days  # noqa: E402
from flexcast.storage import Storage  # noqa: E402

FLEET_SIZES = (1_000, 10_000, 100_000)


def _md(df: pd.DataFrame, floatfmt: str = ".2f") -> str:
    """Minimal GitHub-flavoured markdown table (avoids a tabulate dependency)."""

    def cell(v: object) -> str:
        return format(v, floatfmt) if isinstance(v, float) else str(v)

    header = [str(df.index.name or "")] + [str(c) for c in df.columns]
    lines = ["| " + " | ".join(header) + " |", "|" + "---|" * len(header)]
    for idx, *values in df.itertuples():  # itertuples keeps per-column types (ints stay ints)
        lines.append("| " + " | ".join([str(idx)] + [cell(v) for v in values]) + " |")
    return "\n".join(lines)


def chart(daily: pd.DataFrame) -> bytes:
    wide = daily.pivot(index="target_date", columns="strategy", values="value_gbp").sort_index()
    fig, ax = plt.subplots(figsize=(8, 4.5), dpi=120)
    for strategy in summarise(daily).index:
        perfect = strategy == PERFECT
        ax.plot(
            wide.index,
            wide[strategy].cumsum(),
            label=strategy,
            color="black" if perfect else None,
            linestyle="--" if perfect else "-",
        )
    ax.set_title("Cumulative £ per 10 kWh battery (settled at system price)")
    ax.set_ylabel("£")
    ax.grid(alpha=0.3)
    ax.legend()
    fig.autofmt_xdate()
    buf = io.BytesIO()
    fig.savefig(buf, format="png", bbox_inches="tight", metadata={"Software": None})
    plt.close(fig)
    return buf.getvalue()


def render(
    result: BacktestResult,
    cfg: BacktestConfig,
    sensitivity: pd.DataFrame,
    best_model: str,
) -> str:
    summary = summarise(result.daily)
    table = summary.rename(
        columns={
            "gbp_per_year": "£/battery/year",
            "pct_of_perfect": "% of perfect",
            "mae": "MAE £/MWh",
            "pinball": "pinball",
        }
    )
    fleet = pd.DataFrame(
        {f"{n:,} batteries (£k/yr)": summary["gbp_per_year"] * n / 1000 for n in FLEET_SIZES}
    ).drop(index=PERFECT, errors="ignore")
    b = cfg.battery
    battery = (
        f"{b.capacity_kwh:g} kWh, {b.power_kw:g} kW, {b.round_trip_efficiency:.0%} round trip, "
        f"SoC {b.initial_soc_kwh:g} kWh at start and end, "
        f"degradation {b.degradation_gbp_per_kwh * 100:g}p/kWh throughput"
    )
    return f"""# Backtest results

Generated by `flexcast backtest`; do not edit by hand. Contains BMRS data © Elexon Limited
copyright and database right.

- Test window: {cfg.test_start} to {cfg.test_end} ({summary.loc[PERFECT, "days"]} days with
  complete prices; {len(result.skipped)} skipped). Training from {cfg.train_start}, expanding
  window, retrained every {cfg.retrain_every_days} days.
- Decision: D-1 {cfg.decision_at:%H:%M} Europe/London. Features use only data available before it.
- Battery: {battery}. Settled at the system sell price (single imbalance price).
- Strategies optimise the battery on their p50 forecast; `perfect` optimises on actual prices.
  Leaving the battery idle earns £0: a strategy below zero is worse than doing nothing.

## Summary

{_md(table)}

![Cumulative £ by strategy](results.png)

## Fleet scaling (linear)

{_md(fleet, ".0f")}

Linear scaling ignores price impact: a 100k-battery fleet (500 MW) would move the prices it
trades against, so the 100k figure is an upper bound.

## Degradation sensitivity (£/battery/year; % of perfect in brackets)

{_md(sensitivity)}

## Worst 10 days for `{best_model}` (£ short of perfect foresight)

{_md(worst_days(result.daily, best_model))}

## Caveats

- Historical system prices are the latest settlement revision, not the first-published value;
  features may see slightly better prices than were available in real time.
- One representative battery; perfect execution; symmetric buy/sell price; no network charges.
- Degradation is a flat £/kWh throughput cost (see sensitivity table).
"""


def write(
    storage: Storage,
    result: BacktestResult,
    cfg: BacktestConfig,
    sensitivity: pd.DataFrame,
    best_model: str,
) -> None:
    storage.write_text(render(result, cfg, sensitivity, best_model), "results.md")
    storage.write_bytes(chart(result.daily), "results.png")
